-- ============================================================
-- Migration: สำหรับฐานข้อมูลที่ deploy ไปแล้วเท่านั้น (ฐานข้อมูลใหม่ไม่ต้องรัน เพราะ schema.sql มีให้ครบแล้ว)
-- ครอบคลุม 3 การเปลี่ยนแปลง:
--   1) เพิ่มฟิลด์ที่อยู่แบบ dropdown (จังหวัด/อำเภอ/ตำบล/รหัสไปรษณีย์) ในตาราง users
--   2) ลดตัวเลือกบริษัทขนส่ง (ถ้าต้องการ)
--   3) เพิ่มการคิดค่าธรรมเนียมต่ออายุยืมในตาราง borrow_records
-- รันไฟล์นี้ผ่าน Railway Query tab หรือ mysql client ที่ต่อกับฐานข้อมูลเดิม
-- ============================================================
USE book_borrow_system;

ALTER TABLE users
  ADD COLUMN address_detail VARCHAR(255) AFTER address,
  ADD COLUMN subdistrict   VARCHAR(100) AFTER address_detail,
  ADD COLUMN district      VARCHAR(100) AFTER subdistrict,
  ADD COLUMN province      VARCHAR(100) AFTER district,
  ADD COLUMN postal_code   VARCHAR(10)  AFTER province;

-- หมายเหตุ: คอลัมน์ address เดิมยังใช้งานต่อได้ตามปกติ (เก็บที่อยู่แบบข้อความเต็ม
-- ที่ระบบสร้างให้อัตโนมัติจากฟิลด์ข้างบนตอนผู้ใช้สมัคร/แก้ไขโปรไฟล์ผ่านฟอร์มใหม่)
-- ผู้ใช้เดิมที่สมัครไว้ก่อนหน้านี้จะมีแค่คอลัมน์ address (ข้อความเดิม) ส่วนฟิลด์ใหม่จะเป็นค่าว่าง
-- จนกว่าจะเข้าไปแก้ไขโปรไฟล์อีกครั้งผ่านฟอร์ม dropdown ใหม่

-- ------------------------------------------------------------
-- (ถ้าต้องการ) ลดตัวเลือกบริษัทขนส่งที่ลูกค้าเลือกได้เหลือ 1-2 บริษัท
-- ฐานข้อมูลใหม่ (schema.sql) seed มาแค่ 2 บริษัทให้แล้ว ส่วนฐานข้อมูลเดิมที่เคยมี 3 บริษัท
-- ใช้คำสั่งด้านล่างปิดการใช้งานบริษัทที่ไม่ต้องการ (ปิดไว้ไม่ลบ เพราะรายการยืมเก่าอาจอ้างอิงอยู่)
-- ตัวอย่าง: ปิด Flash Express เหลือแค่ Kerry Express กับไปรษณีย์ไทย
-- ------------------------------------------------------------
-- UPDATE shipping_companies SET is_active = 0 WHERE name = 'Flash Express';

-- ------------------------------------------------------------
-- เพิ่มการคิดค่าธรรมเนียมต่ออายุยืม (ต้องชำระก่อนคำขอจึงมีผลจริง)
-- ------------------------------------------------------------
ALTER TABLE borrow_records
  ADD COLUMN extend_fee DECIMAL(10,2) AFTER extend_status,
  ADD COLUMN extend_payment_status ENUM('none','pending','pending_verification','paid') NOT NULL DEFAULT 'none' AFTER extend_fee,
  ADD COLUMN extend_payment_slip_image VARCHAR(255) AFTER extend_payment_status,
  ADD COLUMN extend_paid_at DATETIME AFTER extend_payment_slip_image;

-- ------------------------------------------------------------
-- (ถ้าต้องการ) เพิ่มหนังสือตัวอย่างให้ครบทั้ง 4 หมวดหมู่ สำหรับฐานข้อมูลเดิมที่มีแค่ 3 เล่มแรก
-- (ไม่ซ้ำกับ 3 เล่มเดิม: The Quantum Future / Space and Light / Mindful Leadership)
-- ------------------------------------------------------------
